-- One authoritative, lightweight advisor assignment per client.
-- Historical evidence is kept in app_private so the initial decision remains auditable
-- without turning historical rows into operational orders.

begin;

set local lock_timeout = '5s';
set local statement_timeout = '120s';

create schema if not exists app_private;

alter table public.clients
  add column if not exists advisor_assignment_source text,
  add column if not exists advisor_assignment_evidence_at timestamptz,
  add column if not exists advisor_assignment_reason text,
  add column if not exists advisor_assignment_updated_at timestamptz,
  add column if not exists advisor_assignment_batch_key text;

alter table public.clients
  add constraint clients_advisor_assignment_source_check
  check (
    advisor_assignment_source is null
    or advisor_assignment_source in (
      'historical_backfill',
      'live_backfill',
      'live_orphan_rescue',
      'manual',
      'orphan'
    )
  ),
  add constraint clients_advisor_assignment_consistency_check
  check (
    (
      primary_advisor_id is null
      and advisor_assignment_source in ('orphan')
      and advisor_assignment_evidence_at is null
    )
    or (
      primary_advisor_id is null
      and advisor_assignment_source is null
      and advisor_assignment_evidence_at is null
    )
    or (
      primary_advisor_id is not null
      and advisor_assignment_source in (
        'historical_backfill',
        'live_backfill',
        'live_orphan_rescue',
        'manual'
      )
      and advisor_assignment_evidence_at is not null
    )
  );

comment on column public.clients.primary_advisor_id is
  'Asesor adjudicado vigente. NULL identifica una cartera huérfana.';
comment on column public.clients.advisor_assignment_source is
  'Origen de la adjudicación vigente; no se recalcula con cada compra.';
comment on column public.clients.advisor_assignment_evidence_at is
  'Fecha de la evidencia usada para adjudicar o de la decisión manual.';
comment on column public.clients.advisor_assignment_reason is
  'Regla o motivo breve de la adjudicación vigente.';
comment on column public.clients.advisor_assignment_updated_at is
  'Fecha en que cambió la adjudicación, independiente de la actividad comercial.';
comment on column public.clients.advisor_assignment_batch_key is
  'Lote auditable que originó la adjudicación, cuando corresponda.';

create index if not exists clients_primary_advisor_active_idx
  on public.clients (primary_advisor_id, id)
  where is_active = true and primary_advisor_id is not null;

create index if not exists clients_active_orphan_idx
  on public.clients (id)
  where is_active = true and primary_advisor_id is null;

create or replace function public.is_current_active_advisor_v1(p_user_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $function$
  select p_user_id is not null
    and exists (
      select 1
      from public.profiles profile
      where profile.id = p_user_id
        and profile.is_active = true
        and exists (
          select 1
          from public.user_roles role_row
          where role_row.user_id = profile.id
            and role_row.role::text = 'advisor'
        )
    );
$function$;

revoke all on function public.is_current_active_advisor_v1(uuid)
  from public, anon;
grant execute on function public.is_current_active_advisor_v1(uuid)
  to authenticated, service_role;

create or replace function app_private.guard_client_advisor_assignment_v1()
returns trigger
language plpgsql
set search_path = ''
as $function$
declare
  v_assignment_changed boolean;
  v_can_manage boolean;
begin
  v_assignment_changed := tg_op = 'INSERT'
    or new.primary_advisor_id is distinct from old.primary_advisor_id
    or new.advisor_assignment_source is distinct from old.advisor_assignment_source
    or new.advisor_assignment_evidence_at is distinct from old.advisor_assignment_evidence_at
    or new.advisor_assignment_reason is distinct from old.advisor_assignment_reason
    or new.advisor_assignment_updated_at is distinct from old.advisor_assignment_updated_at
    or new.advisor_assignment_batch_key is distinct from old.advisor_assignment_batch_key;

  if not v_assignment_changed then
    return new;
  end if;

  v_can_manage := public.is_master_or_admin()
    or current_user in ('postgres', 'supabase_admin', 'service_role');

  if tg_op = 'UPDATE' and not v_can_manage then
    raise exception 'client_advisor_assignment_requires_master'
      using errcode = '42501';
  end if;

  if tg_op = 'INSERT' and new.primary_advisor_id is not null and not v_can_manage then
    raise exception 'client_advisor_assignment_requires_master'
      using errcode = '42501';
  end if;

  if new.primary_advisor_id is not null
     and not public.is_current_active_advisor_v1(new.primary_advisor_id) then
    raise exception 'client_primary_advisor_must_be_current_and_active'
      using errcode = '23514';
  end if;

  if tg_op = 'INSERT' then
    if new.primary_advisor_id is null then
      new.advisor_assignment_source := 'orphan';
      new.advisor_assignment_evidence_at := null;
      new.advisor_assignment_reason := coalesce(
        nullif(trim(new.advisor_assignment_reason), ''),
        'client_created_without_assignment'
      );
      new.advisor_assignment_batch_key := null;
    else
      new.advisor_assignment_source := coalesce(
        new.advisor_assignment_source,
        'manual'
      );
      new.advisor_assignment_evidence_at := coalesce(
        new.advisor_assignment_evidence_at,
        now()
      );
      new.advisor_assignment_reason := coalesce(
        nullif(trim(new.advisor_assignment_reason), ''),
        'manual_assignment_at_client_creation'
      );
    end if;
    new.advisor_assignment_updated_at := now();
    return new;
  end if;

  if new.primary_advisor_id is distinct from old.primary_advisor_id then
    if new.primary_advisor_id is null then
      if new.advisor_assignment_source is not distinct from old.advisor_assignment_source then
        new.advisor_assignment_source := 'orphan';
      end if;
      new.advisor_assignment_evidence_at := null;
      if new.advisor_assignment_reason is not distinct from old.advisor_assignment_reason then
        new.advisor_assignment_reason := 'manual_unassignment';
      end if;
      if new.advisor_assignment_batch_key is not distinct from old.advisor_assignment_batch_key then
        new.advisor_assignment_batch_key := null;
      end if;
    else
      if new.advisor_assignment_source is not distinct from old.advisor_assignment_source then
        new.advisor_assignment_source := 'manual';
      end if;
      if new.advisor_assignment_evidence_at is not distinct from old.advisor_assignment_evidence_at then
        new.advisor_assignment_evidence_at := now();
      end if;
      if new.advisor_assignment_reason is not distinct from old.advisor_assignment_reason then
        new.advisor_assignment_reason := 'manual_master_assignment';
      end if;
      if new.advisor_assignment_batch_key is not distinct from old.advisor_assignment_batch_key then
        new.advisor_assignment_batch_key := null;
      end if;
    end if;
  end if;

  new.advisor_assignment_updated_at := now();
  return new;
end;
$function$;

revoke all on function app_private.guard_client_advisor_assignment_v1()
  from public, anon, authenticated;

drop trigger if exists clients_advisor_assignment_guard_v1 on public.clients;
create trigger clients_advisor_assignment_guard_v1
before insert or update on public.clients
for each row
execute function app_private.guard_client_advisor_assignment_v1();

create or replace function public.trg_clients_set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $function$
begin
  if current_setting('app.preserve_clients_updated_at', true) = 'on' then
    new.updated_at := old.updated_at;
  else
    new.updated_at := now();
  end if;
  return new;
end;
$function$;

create table app_private.client_advisor_assignment_batches_v1 (
  batch_key text primary key,
  historical_cutoff date not null,
  source_workbook text not null,
  source_workbook_sha256 text not null
    check (source_workbook_sha256 ~ '^[0-9a-f]{64}$'),
  source_order_rows integer not null check (source_order_rows >= 0),
  mapped_historical_orders integer not null check (mapped_historical_orders >= 0),
  evidence_client_rows integer not null check (evidence_client_rows >= 0),
  active_advisor_evidence_clients integer not null
    check (active_advisor_evidence_clients >= 0),
  audit_summary jsonb not null default '{}'::jsonb,
  imported_at timestamptz not null default now()
);

create table app_private.client_advisor_historical_evidence_v1 (
  batch_key text not null
    references app_private.client_advisor_assignment_batches_v1(batch_key)
    on delete restrict,
  client_id bigint not null
    references public.clients(id)
    on delete restrict,
  canonical_legacy_control text not null,
  latest_active_advisor_id uuid
    references public.profiles(id)
    on delete restrict,
  latest_active_advisor_name text,
  active_advisor_evidence_at timestamptz,
  active_advisor_legacy_order_control bigint,
  last_historical_order_at timestamptz not null,
  historical_order_count integer not null check (historical_order_count > 0),
  active_advisor_order_count integer not null
    check (
      active_advisor_order_count >= 0
      and active_advisor_order_count <= historical_order_count
    ),
  imported_at timestamptz not null default now(),
  primary key (batch_key, client_id),
  unique (batch_key, canonical_legacy_control),
  check (
    (
      active_advisor_order_count = 0
      and latest_active_advisor_id is null
      and latest_active_advisor_name is null
      and active_advisor_evidence_at is null
      and active_advisor_legacy_order_control is null
    )
    or (
      active_advisor_order_count > 0
      and latest_active_advisor_id is not null
      and latest_active_advisor_name is not null
      and active_advisor_evidence_at is not null
      and active_advisor_legacy_order_control is not null
    )
  )
);

create index client_advisor_historical_evidence_client_idx
  on app_private.client_advisor_historical_evidence_v1 (client_id);
create index client_advisor_historical_evidence_advisor_idx
  on app_private.client_advisor_historical_evidence_v1 (
    latest_active_advisor_id,
    active_advisor_evidence_at desc
  )
  where latest_active_advisor_id is not null;

alter table app_private.client_advisor_assignment_batches_v1
  enable row level security;
alter table app_private.client_advisor_historical_evidence_v1
  enable row level security;

revoke all on app_private.client_advisor_assignment_batches_v1
  from public, anon, authenticated;
revoke all on app_private.client_advisor_historical_evidence_v1
  from public, anon, authenticated;
grant usage on schema app_private to service_role;
grant select, insert, update, delete
  on app_private.client_advisor_assignment_batches_v1
  to service_role;
grant select, insert, update, delete
  on app_private.client_advisor_historical_evidence_v1
  to service_role;

comment on table app_private.client_advisor_assignment_batches_v1 is
  'Auditoría del lote usado para adjudicar la cartera inicial.';
comment on table app_private.client_advisor_historical_evidence_v1 is
  'Una fila por cliente con compras históricas válidas; no es una orden operativa.';

insert into app_private.client_advisor_assignment_batches_v1 (
  batch_key,
  historical_cutoff,
  source_workbook,
  source_workbook_sha256,
  source_order_rows,
  mapped_historical_orders,
  evidence_client_rows,
  active_advisor_evidence_clients,
  audit_summary
)
