  ('6329', null, null, null, '2026-05-29T00:00:00', 1, 0),
  ('6330', 'Mariángela Montiel', '2026-05-29T00:00:00', 32023, '2026-05-29T00:00:00', 1, 1),
  ('6331', null, null, null, '2026-05-29T00:00:00', 1, 0),
  ('6332', null, null, null, '2026-05-29T00:00:00', 1, 0),
  ('6333', 'Yujanir Aular', '2026-05-29T00:00:00', 32026, '2026-05-29T00:00:00', 1, 1),
  ('6334', 'Mariángela Montiel', '2026-05-29T00:00:00', 32027, '2026-05-29T00:00:00', 1, 1),
  ('6335', null, null, null, '2026-05-29T00:00:00', 1, 0),
  ('6336', 'Yujanir Aular', '2026-05-29T00:00:00', 32038, '2026-05-29T00:00:00', 1, 1),
  ('6337', 'Mariángela Montiel', '2026-05-29T00:00:00', 32041, '2026-05-29T00:00:00', 1, 1),
  ('6338', 'Ramón Viviescas', '2026-05-29T00:00:00', 32042, '2026-05-29T00:00:00', 1, 1),
  ('6339', 'Mariángela Montiel', '2026-05-29T00:00:00', 32043, '2026-05-29T00:00:00', 1, 1),
  ('6340', 'Jacqueline Aular', '2026-05-29T00:00:00', 32051, '2026-05-29T00:00:00', 1, 1),
  ('6341', 'Jacqueline Aular', '2026-05-30T00:00:00', 32055, '2026-05-30T00:00:00', 1, 1),
  ('6342', null, null, null, '2026-05-30T00:00:00', 1, 0),
  ('6343', null, null, null, '2026-05-31T00:00:00', 1, 0),
  ('6344', 'Ramón Viviescas', '2026-05-31T00:00:00', 32085, '2026-05-31T00:00:00', 1, 1),
  ('6345', 'Ramón Viviescas', '2026-05-31T00:00:00', 32090, '2026-05-31T00:00:00', 1, 1)
),
resolved_evidence as (
  select
    'client_primary_advisor_backfill_2026_08_21_v1'::text as batch_key,
    alias_row.client_id,
    raw_evidence.canonical_legacy_control,
    advisor.id as latest_active_advisor_id,
    raw_evidence.latest_active_advisor_name,
    case
      when raw_evidence.active_advisor_evidence_at is null then null
      else raw_evidence.active_advisor_evidence_at::timestamp
        at time zone 'America/Caracas'
    end as active_advisor_evidence_at,
    raw_evidence.active_advisor_legacy_order_control,
    raw_evidence.last_historical_order_at::timestamp
      at time zone 'America/Caracas' as last_historical_order_at,
    raw_evidence.historical_order_count,
    raw_evidence.active_advisor_order_count
  from raw_evidence
  join public.client_legacy_aliases alias_row
    on alias_row.source = 'clientes_final_2026-06-01'
   and alias_row.legacy_control = raw_evidence.canonical_legacy_control
  left join lateral (
    select profile.id
    from public.profiles profile
    where profile.full_name = raw_evidence.latest_active_advisor_name
      and public.is_current_active_advisor_v1(profile.id)
    order by profile.id
    limit 1
  ) advisor on true
)
insert into app_private.client_advisor_historical_evidence_v1 (
  batch_key,
  client_id,
  canonical_legacy_control,
  latest_active_advisor_id,
  latest_active_advisor_name,
  active_advisor_evidence_at,
  active_advisor_legacy_order_control,
  last_historical_order_at,
  historical_order_count,
  active_advisor_order_count
)
select
  batch_key,
  client_id,
  canonical_legacy_control,
  latest_active_advisor_id,
  latest_active_advisor_name,
  active_advisor_evidence_at,
  active_advisor_legacy_order_control,
  last_historical_order_at,
  historical_order_count,
  active_advisor_order_count
from resolved_evidence;

do $block$
declare
  v_rows integer;
  v_active_rows integer;
begin
  select
    count(*),
    count(*) filter (where latest_active_advisor_id is not null)
  into v_rows, v_active_rows
  from app_private.client_advisor_historical_evidence_v1
  where batch_key = 'client_primary_advisor_backfill_2026_08_21_v1';

  if v_rows <> 6247 or v_active_rows <> 5078 then
    raise exception
      'historical_assignment_evidence_mismatch rows=% active_rows=%',
      v_rows,
      v_active_rows;
  end if;
end;
$block$;

create or replace function app_private.run_client_primary_advisor_backfill_v1(
  p_batch_key text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_cutoff date;
  v_assigned integer := 0;
  v_orphaned integer := 0;
  v_result jsonb;
begin
  perform pg_advisory_xact_lock(
    hashtextextended('client_primary_advisor_backfill_v1', 0)
  );

  select batch.historical_cutoff
  into v_cutoff
  from app_private.client_advisor_assignment_batches_v1 batch
  where batch.batch_key = p_batch_key;

  if v_cutoff is null then
    raise exception 'client_advisor_assignment_batch_not_found: %', p_batch_key;
  end if;

  perform set_config('app.preserve_clients_updated_at', 'on', true);

  with active_advisors as materialized (
    select profile.id
    from public.profiles profile
    where profile.is_active = true
      and exists (
        select 1
        from public.user_roles role_row
        where role_row.user_id = profile.id
          and role_row.role::text = 'advisor'
      )
  ),
  historical_candidates as materialized (
    select
      evidence.client_id,
      evidence.latest_active_advisor_id as advisor_id,
      evidence.active_advisor_evidence_at as evidence_at,
      evidence.active_advisor_legacy_order_control as evidence_order_id,
      'historical_backfill'::text as assignment_source,
      1 as source_priority
    from app_private.client_advisor_historical_evidence_v1 evidence
    join active_advisors active_advisor
      on active_advisor.id = evidence.latest_active_advisor_id
    where evidence.batch_key = p_batch_key
  ),
  live_candidates as materialized (
    select distinct on (order_row.client_id)
      order_row.client_id,
      order_row.attributed_advisor_id as advisor_id,
      order_row.created_at as evidence_at,
      order_row.id as evidence_order_id,
      'live_backfill'::text as assignment_source,
      2 as source_priority
    from public.orders order_row
    join active_advisors active_advisor
      on active_advisor.id = order_row.attributed_advisor_id
    where order_row.client_id is not null
      and order_row.status <> 'cancelled'::public.order_status
      and order_row.created_at >= v_cutoff::timestamptz
    order by order_row.client_id, order_row.created_at desc, order_row.id desc
  ),
  winners as materialized (
    select distinct on (candidate.client_id)
      candidate.client_id,
      candidate.advisor_id,
      candidate.evidence_at,
      candidate.assignment_source
    from (
      select * from historical_candidates
      union all
      select * from live_candidates
    ) candidate
    order by
      candidate.client_id,
      candidate.evidence_at desc,
      candidate.source_priority desc,
      candidate.evidence_order_id desc
  )
  update public.clients client
  set
    primary_advisor_id = winner.advisor_id,
    advisor_assignment_source = winner.assignment_source,
    advisor_assignment_evidence_at = winner.evidence_at,
    advisor_assignment_reason = case winner.assignment_source
      when 'live_backfill' then 'most_recent_current_active_advisor_since_cutoff'
      else 'most_recent_current_active_advisor_before_cutoff'
    end,
    advisor_assignment_batch_key = p_batch_key
  from winners winner
  where client.id = winner.client_id
    and client.is_active = true
    and client.primary_advisor_id is null
    and client.advisor_assignment_source is null;

  get diagnostics v_assigned = row_count;

  update public.clients client
  set
    primary_advisor_id = null,
    advisor_assignment_source = 'orphan',
    advisor_assignment_evidence_at = null,
    advisor_assignment_reason = case
      when exists (
        select 1
        from app_private.client_advisor_historical_evidence_v1 evidence
        where evidence.batch_key = p_batch_key
          and evidence.client_id = client.id
      ) then 'historical_orders_but_no_current_active_advisor'
      when exists (
        select 1
        from public.orders order_row
        where order_row.client_id = client.id
          and order_row.status <> 'cancelled'::public.order_status
          and order_row.created_at >= v_cutoff::timestamptz
      ) then 'live_orders_but_no_current_active_advisor'
      else 'no_valid_orders_in_either_source'
    end,
    advisor_assignment_batch_key = p_batch_key
  where client.is_active = true
    and client.primary_advisor_id is null
    and client.advisor_assignment_source is null;

  get diagnostics v_orphaned = row_count;

  perform set_config('app.preserve_clients_updated_at', 'off', true);

  select jsonb_build_object(
    'batchKey', p_batch_key,
    'assignedByThisRun', v_assigned,
    'orphanedByThisRun', v_orphaned,
    'activeClients', count(*) filter (where client.is_active),
    'assignedActiveClients', count(*) filter (
      where client.is_active and client.primary_advisor_id is not null
    ),
    'orphanActiveClients', count(*) filter (
      where client.is_active and client.primary_advisor_id is null
    )
  )
  into v_result
  from public.clients client;

  return v_result;
exception
  when others then
    perform set_config('app.preserve_clients_updated_at', 'off', true);
    raise;
end;
$function$;

revoke all on function app_private.run_client_primary_advisor_backfill_v1(text)
  from public, anon, authenticated;
grant execute on function app_private.run_client_primary_advisor_backfill_v1(text)
  to service_role;

create or replace function app_private.rescue_orphan_client_from_live_order_v1()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
begin
  if new.client_id is null
     or new.attributed_advisor_id is null
     or new.status = 'cancelled'::public.order_status
     or not public.is_current_active_advisor_v1(new.attributed_advisor_id) then
    return new;
  end if;

  update public.clients client
  set
    primary_advisor_id = new.attributed_advisor_id,
    advisor_assignment_source = 'live_orphan_rescue',
    advisor_assignment_evidence_at = new.created_at,
    advisor_assignment_reason = 'first_live_order_with_current_active_advisor',
    advisor_assignment_batch_key = null
  where client.id = new.client_id
    and client.is_active = true
    and client.primary_advisor_id is null
    and (
      client.advisor_assignment_source is null
      or client.advisor_assignment_source = 'orphan'
    );

  return new;
end;
$function$;

revoke all on function app_private.rescue_orphan_client_from_live_order_v1()
  from public, anon, authenticated;

drop trigger if exists orders_rescue_orphan_client_advisor_v1 on public.orders;
create trigger orders_rescue_orphan_client_advisor_v1
after insert or update of client_id, attributed_advisor_id, status
on public.orders
for each row
execute function app_private.rescue_orphan_client_from_live_order_v1();

select app_private.run_client_primary_advisor_backfill_v1(
  'client_primary_advisor_backfill_2026_08_21_v1'
);

commit;
